<?php
namespace App\Livewire\Tenant\Maintenance; use App\Livewire\Concerns\InteractsWithAuthenticatedUser; use App\Livewire\Concerns\InteractsWithRoleShells; use App\Models\MaintenanceRequest; use App\Models\MaintenanceRequestPhoto; use App\Models\Occupancy; use App\Support\WorkflowNotifier; use Illuminate\View\View; use Livewire\Component; use Livewire\WithFileUploads;
class Index extends Component {use InteractsWithAuthenticatedUser,InteractsWithRoleShells,WithFileUploads; public ?int $occupancyId=null; public string $category=''; public string $priority='normal'; public string $title=''; public string $description=''; public mixed $photo=null; public function submit():void{$this->validate(['occupancyId'=>['required','integer'],'category'=>['required','in:plumbing,electrical,water_supply,door_lock,roof_ceiling,wall_floor,kitchen,bathroom,appliance_fitting,security,other'],'priority'=>['required','in:low,normal,urgent'],'title'=>['required','string','max:160'],'description'=>['required','string','min:10','max:2000'],'photo'=>['nullable','image','mimes:jpg,jpeg,png,webp','max:5120']]);$o=Occupancy::query()->with('property')->where('tenant_id',$this->currentUserId())->where('status','active')->findOrFail($this->occupancyId);$r=MaintenanceRequest::create(['occupancy_id'=>$o->id,'property_id'=>$o->property_id,'tenant_id'=>$o->tenant_id,'landlord_id'=>$o->property->landlord_id,'category'=>$this->category,'priority'=>$this->priority,'title'=>$this->title,'description'=>$this->description]);$r->events()->create(['actor_id'=>$this->currentUserId(),'event_type'=>'submitted']);if($this->photo){$p=$this->photo->store('maintenance-requests/'.$r->id.'/tenant','local');MaintenanceRequestPhoto::create(['maintenance_request_id'=>$r->id,'uploaded_by_id'=>$this->currentUserId(),'source'=>'tenant','file_path'=>$p,'original_name'=>$this->photo->getClientOriginalName(),'file_size'=>$this->photo->getSize()]);}app(WorkflowNotifier::class)->notify($o->property->landlord,'maintenance-submitted:'.$r->id,'New maintenance request for '.$o->property->title,($r->priority==='urgent'?'Urgent: ':'').$r->title,route('landlord.maintenance.show',$r),'maintenance','View request');$this->reset('category','title','description','photo');session()->flash('status','Maintenance request submitted.');} public function render():View{$o=Occupancy::query()->where('tenant_id',$this->currentUserId())->where('status','active')->with('property')->get();$requests=MaintenanceRequest::query()->where('tenant_id',$this->currentUserId())->with('property')->latest()->get();return view('livewire.tenant.maintenance.index',['occupancies'=>$o,'requests'=>$requests])->layout('layouts.dashboard-shell',$this->tenantShell('Maintenance'));}}
